SELECT 
    *
FROM `bill`
WHERE user_id = #{userId}

    AND `category_id` = #{categoryId}


	AND YEAR(`bill_date`) = #{year}


	AND MONTH(`bill_date`) = #{month}


	AND `is_consume` = #{isConsume}

ORDER BY `bill_date`

    SELECT 
        *
    FROM `bill`
    WHERE user_id = #{userId}
    AND `bill_date` >= #{startMonth}
    AND `bill_date` <= last_day(#{endMonth})

    	AND `is_consume` = #{isConsume}

	ORDER BY `bill_date`
